import os, json
from pdfminer.high_level import extract_text

def safe(s):
    return "".join([c if c.isalnum() or c in "-_" else "_" for c in s[:100]])

pdf_map=json.load(open("/tmp/oral_pdf_map.json"))

fudan_any=[]
for title, url in pdf_map.items():
    path=os.path.join("/tmp/pdfs", safe(title)+".pdf")
    if not os.path.exists(path):
        continue
    try:
        text=extract_text(path, maxpages=3)
    except:
        continue
    if "fudan" in text.lower():
        fudan_any.append((title, text.lower().find("fudan")))
        print(f"Found Fudan in {title}: pos {text.lower().find('fudan')}")
